package org.sleepwell.app;

import android.content.*;
import android.database.sqlite.SQLiteDatabase;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import org.json.*;

/** Explicit recurring ordinary wake alarms; profile starts do not start tracking or a relative timer. */
final class NapProfilesWeekly {
 private static final Object JOURNAL=new Object();private static final AtomicLong epoch=new AtomicLong();private static final java.util.concurrent.atomic.AtomicInteger replacements=new java.util.concurrent.atomic.AtomicInteger();private static boolean replacing(){return replacements.get()>0;}
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("nap_profiles_weekly_v1",Context.MODE_PRIVATE);}
 static void replacing(Context c){replacements.incrementAndGet();epoch.incrementAndGet();}
 static void replacementFinished(){replacements.updateAndGet(n->Math.max(0,n-1));epoch.incrementAndGet();}
 /** Post-commit only. Definitions and imported/ordinary alarm rows are not changed. */
 static void replaced(Context c){synchronized(JOURNAL){epoch.incrementAndGet();if(!prefs(c).edit().clear().commit())throw new IllegalStateException("Data was restored, but weekly profile authority cleanup needs attention. Reopen Nap profiles.");}}
 static String canonical(Alarm alarm){JSONObject json=alarm.json();json.remove("scheduleError");return json.toString();}
 static boolean owns(Context context,Alarm alarm){if(alarm==null||alarm.nap!=null||alarm.napInvalid||alarm.date!=null||alarm.days.isEmpty())return false;try{Map<String,?> snapshot=prefs(context).getAll();Object raw=snapshot.get("row_"+alarm.id);if(!(raw instanceof String text)||text.isEmpty())return false;JSONObject index=new JSONObject(text);Object stored=snapshot.get("group_"+index.getString("group"));if(!(stored instanceof String encoded))return false;Group group=Group.read(new JSONObject(encoded));if(!group.nonce.equals(nonce(alarm))||!group.nonce.equals(index.getString("nonce"))||group.revision!=index.getInt("revision")||group.stage.equals("CANCELLED"))return false;for(Row row:group.rows)if(row.id==alarm.id&&row.signature.equals(index.getString("signature")))return matches(group,row,alarm);return false;}catch(Exception invalid){return false;}}
 static String nonce(Alarm alarm){return alarm.json().optString("weeklyNapOwner","");}
 private static Alarm marked(Alarm alarm,String nonce){try{JSONObject json=alarm.json().put("weeklyNapOwner",nonce);Alarm marked=Alarm.read(json);if(!nonce.equals(nonce(marked)))throw new IllegalStateException("Weekly alarm ownership is unavailable in this build. No alarms were applied.");return marked;}catch(JSONException impossible){throw new IllegalStateException("Weekly alarm ownership could not be encoded.");}}
 static Set<Integer> wakeDays(NapProfiles.Profile profile,NapProfiles.Entry entry){Set<Integer> days=new TreeSet<>();int shift=(entry.minute+entry.duration)/1440;for(int day:profile.weekdays)days.add((day-1+shift)%7+1);return days;}
 static Alarm template(int id,NapProfiles.Profile profile,int index){NapProfiles.Entry entry=profile.entries.get(index);Alarm alarm=new Alarm(id);int minute=(entry.minute+entry.duration)%1440;alarm.hour=minute/60;alarm.minute=minute%60;alarm.days=new TreeSet<>(wakeDays(profile,entry));alarm.smartWindow=0;alarm.bedtime=AlarmBedtime.OFF;alarm.label=profile.name+" · weekly nap "+(index+1);alarm.enabled=false;return alarm;}
 static long startFor(long end,NapProfiles.Entry entry,ZoneId zone){LocalDate endDay=Instant.ofEpochMilli(end).atZone(zone).toLocalDate();return endDay.minusDays((entry.minute+entry.duration)/1440).atTime(entry.minute/60,entry.minute%60).atZone(zone).toInstant().toEpochMilli();}
 static final class Review {
  final NapProfiles.Profile profile;final ZoneId zone;final long wall,elapsed,boot;final String device;final List<Long> starts,ends;final List<String> skips;
  Review(NapProfiles.Profile profile,ZoneId zone,long wall,long elapsed,long boot,String device){if(profile==null||!profile.weekly||zone==null||wall<=0||elapsed<0||boot<0||device==null||device.isEmpty())throw new IllegalArgumentException("Review a saved weekly profile first.");this.profile=profile;this.zone=zone;this.wall=wall;this.elapsed=elapsed;this.boot=boot;this.device=device;List<Long> begins=new ArrayList<>(),wakes=new ArrayList<>();List<String> excluded=new ArrayList<>();for(int n=0;n<profile.entries.size();n++){NapProfiles.Entry entry=profile.entries.get(n);Alarm alarm=template(n+1,profile,n);long wake=alarm.next(wall,zone),start=startFor(wake,entry,zone);String skip="";if(start-wall<60000){LocalDate day=Instant.ofEpochMilli(wake).atZone(zone).toLocalDate();alarm.skip=new AlarmSkip(UUID.randomUUID().toString(),day,alarm.hour,alarm.minute,alarm.days,zone.getId());skip=AlarmSkipJson.encode(alarm.skip).toString();wake=alarm.next(wall,zone);start=startFor(wake,entry,zone);}if(start-wall<60000||wake<=start)throw new IllegalArgumentException("An upcoming weekly window cannot be resolved across this clock change. Choose different times before applying.");begins.add(start);wakes.add(wake);excluded.add(skip);}for(int n=0;n<begins.size();n++)for(int m=n+1;m<begins.size();m++)if(begins.get(n)<wakes.get(m)&&begins.get(m)<wakes.get(n))throw new IllegalArgumentException("Upcoming nap windows overlap after the clock change. Review their times.");starts=List.copyOf(begins);ends=List.copyOf(wakes);skips=List.copyOf(excluded);}
  void check(NapPlan.Clock now){long drift=(now.wall()-wall)-(now.elapsed()-elapsed);if(replacing()||!zone.equals(ZoneId.systemDefault())||boot!=now.boot()||!device.equals(now.device())||now.elapsed()<elapsed||Math.abs(drift)>2000)throw new IllegalArgumentException("Phone time, zone, boot or local data changed. Review the weekly profile again.");for(long start:starts)if(start-now.wall()<60000)throw new IllegalArgumentException("An upcoming start is too close or passed. Review the next weekly windows.");}
  JSONObject json()throws JSONException{return new JSONObject().put("profile",profile.json()).put("zone",zone.getId()).put("wall",wall).put("elapsed",elapsed).put("boot",boot).put("device",device);}
  static Review read(JSONObject value)throws JSONException{return new Review(NapProfiles.Profile.read(value.getJSONObject("profile")),ZoneId.of(value.getString("zone")),value.getLong("wall"),value.getLong("elapsed"),value.getLong("boot"),value.getString("device"));}
 }
 static final class Row {
  final int id;final String snapshot,signature;final boolean scheduled,cancelled;
  Row(Alarm alarm,boolean scheduled,boolean cancelled){this.id=alarm.id;this.snapshot=alarm.json().toString();signature=canonical(alarm);this.scheduled=scheduled;this.cancelled=cancelled;if(id<=0||alarm.nap!=null||alarm.napInvalid||alarm.date!=null||alarm.days.isEmpty()||alarm.solar!=null)throw new IllegalArgumentException("Invalid weekly alarm ownership.");}
  Alarm alarm(){try{return Alarm.read(new JSONObject(snapshot));}catch(JSONException bad){throw new IllegalArgumentException("Weekly alarm ownership is unreadable.");}}
  Row scheduled(){return new Row(alarm(),true,cancelled);}Row current(Alarm alarm){return new Row(alarm,scheduled,cancelled);}Row cancelled(){return new Row(alarm(),scheduled,true);}
  JSONObject json()throws JSONException{return new JSONObject().put("alarm",new JSONObject(snapshot)).put("scheduled",scheduled).put("cancelled",cancelled);}
  static Row read(JSONObject json)throws JSONException{if(json.length()!=3||!(json.get("scheduled") instanceof Boolean)||!(json.get("cancelled") instanceof Boolean))throw new JSONException("Invalid weekly row");return new Row(Alarm.read(json.getJSONObject("alarm")),json.getBoolean("scheduled"),json.getBoolean("cancelled"));}
 }
 static final class Group {
  final String id,nonce,stage,error;final int revision;final Review review;final List<Row> rows;final boolean activation,cancellation;
  Group(String id,String nonce,int revision,Review review,List<Row> rows,String stage,String error,boolean activation,boolean cancellation){NapProfiles.uuid(id);NapProfiles.uuid(nonce);if(revision<1||review==null||rows.size()!=review.profile.entries.size()||error==null||error.length()>300||!Set.of("PREPARED","CREATED","SCHEDULING","ACTIVATING","ACTIVE","CANCELLING","CANCELLED","ATTENTION").contains(stage))throw new IllegalArgumentException("Invalid weekly application.");Set<Integer> ids=new HashSet<>();for(Row row:rows)if(!ids.add(row.id)||!nonce.equals(nonce(row.alarm())))throw new IllegalArgumentException("Invalid or duplicate weekly alarm owner.");this.id=id;this.nonce=nonce;this.revision=revision;this.review=review;this.rows=List.copyOf(rows);this.stage=stage;this.error=error;this.activation=activation;this.cancellation=cancellation;}
  Group change(List<Row> rows,String stage,String error,boolean activation,boolean cancellation){if(revision==Integer.MAX_VALUE)throw new IllegalArgumentException("Weekly application revision limit reached.");return new Group(id,nonce,revision+1,review,rows,stage,error,activation,cancellation);}
  JSONObject json()throws JSONException{JSONArray rows=new JSONArray();for(Row row:this.rows)rows.put(row.json());return new JSONObject().put("id",id).put("nonce",nonce).put("revision",revision).put("review",review.json()).put("rows",rows).put("stage",stage).put("error",error).put("activation",activation).put("cancellation",cancellation);}
  static Group read(JSONObject json)throws JSONException{if(json.length()!=9||!(json.get("activation") instanceof Boolean)||!(json.get("cancellation") instanceof Boolean))throw new JSONException("Invalid weekly application");List<Row> rows=new ArrayList<>();JSONArray values=json.getJSONArray("rows");if(values.length()>6)throw new JSONException("Too many weekly rows");for(int n=0;n<values.length();n++)rows.add(Row.read(values.getJSONObject(n)));return new Group(json.getString("id"),json.getString("nonce"),NapProfiles.number(json,"revision"),Review.read(json.getJSONObject("review")),rows,json.getString("stage"),json.getString("error"),json.getBoolean("activation"),json.getBoolean("cancellation"));}
 }
 static List<Group> groups(Context c){List<Group> result=new ArrayList<>();try{Map<String,?> values=prefs(c).getAll();for(Map.Entry<String,?> entry:values.entrySet())if(entry.getKey().startsWith("group_")){if(result.size()>=30||!(entry.getValue() instanceof String text)||text.length()>100000)throw new JSONException("Weekly journal limit");Group group=Group.read(new JSONObject(text));if(!entry.getKey().equals("group_"+group.id))throw new JSONException("Weekly journal identity");result.add(group);}result.sort(Comparator.comparingLong((Group g)->g.review.wall));return List.copyOf(result);}catch(JSONException|RuntimeException bad){throw new IllegalStateException("Weekly nap applications are unreadable. Existing alarms were not changed.",bad);}}
 private static Group get(Context c,String id){for(Group group:groups(c))if(group.id.equals(id))return group;throw new IllegalArgumentException("This weekly application was removed or invalidated by data replacement.");}
 private static void guard(long expected){if(replacing()||expected!=epoch.get())throw new IllegalStateException("Local data is being replaced or weekly ownership changed. Reopen Nap profiles.");}
 private static void put(Context c,Group group,long expected){synchronized(JOURNAL){guard(expected);SharedPreferences prefs=prefs(c);try{String previous=prefs.getString("group_"+group.id,"");if(previous.isEmpty()){if(group.revision!=1||groups(c).size()>=30)throw new IllegalStateException("Resolve or detach an old weekly application before adding another.");}else{Group old=Group.read(new JSONObject(previous));if(!old.nonce.equals(group.nonce)||old.revision+1!=group.revision)throw new IllegalStateException("This weekly application changed. Reopen it.");}SharedPreferences.Editor edit=prefs.edit().putString("group_"+group.id,group.json().toString());for(Row row:group.rows){if(row.cancelled||group.stage.equals("CANCELLED"))edit.remove("row_"+row.id);else edit.putString("row_"+row.id,new JSONObject().put("group",group.id).put("nonce",group.nonce).put("revision",group.revision).put("signature",row.signature).toString());}guard(expected);if(!edit.commit())throw new IllegalStateException("Weekly application ownership could not be saved.");}catch(JSONException bad){throw new IllegalStateException("Weekly application could not be encoded.",bad);}}}
 private static boolean matches(Group group,Row row,Alarm actual){
  if(actual==null||actual.id!=row.id||!group.nonce.equals(nonce(actual)))return false;
  String current=canonical(actual);Alarm saved=row.alarm();
  for(int variant=0;variant<2;variant++){
   Alarm expected=Alarm.read(saved.json());
   if(variant==1){
    // Normal completion may consume the reviewed first-window skip. User changes revoke the nonce.
    if(expected.skip==null||expected.skipInvalid||actual.skip!=null||actual.skipInvalid)break;
    expected.skip=null;
   }
   if(canonical(expected).equals(current))return true;
   expected.enabled=!group.cancellation;
   if(canonical(expected).equals(current))return true;
  }
  return false;
 }
 private static void access(Context context){if(Prefs.flag(context,"ringing"))throw new IllegalArgumentException("Finish the active alarm before changing a weekly profile.");if(!AlarmScheduling.port.allowed(context))throw new SecurityException("Enable Alarms & reminders in Setup, then retry the reviewed weekly application.");String denied=Naps.ports.create(context).access();if(!denied.isEmpty())throw new SecurityException(denied);}
 static Review review(Context c,String id,int revision){NapProfiles.Profile profile=new NapProfilesStore(c).profile(id);if(profile.revision!=revision||!profile.weekly)throw new IllegalArgumentException("The weekly definition changed. Reopen it.");NapPlan.Clock now=Naps.clock(c);return new Review(profile,ZoneId.systemDefault(),now.wall(),now.elapsed(),now.boot(),now.device());}
 static Group apply(Context c,Review review){BackupRuntime.admitted();long own=epoch.get();guard(own);review.check(Naps.clock(c));NapProfiles.Profile profile=new NapProfilesStore(c).profile(review.profile.id);if(profile.revision!=review.profile.revision)throw new IllegalArgumentException("The saved definition changed. Review it again.");access(c);for(Group previous:groups(c))if(previous.review.profile.id.equals(profile.id)&&!previous.stage.equals("CANCELLED"))throw new IllegalArgumentException("This profile already has a weekly application. Cancel or detach it before applying another.");String groupId=UUID.randomUUID().toString(),groupNonce=UUID.randomUUID().toString();List<Row> rows=new ArrayList<>();try(Store store=Records.open(c)){int maximum=store.alarms().stream().mapToInt(a->a.id).max().orElse(0);if(maximum>Integer.MAX_VALUE-profile.entries.size())throw new IllegalArgumentException("No alarm slots remain.");for(int n=0;n<profile.entries.size();n++){Alarm alarm=marked(template(maximum+n+1,profile,n),groupNonce);String skipped=review.skips.get(n);if(!skipped.isEmpty())try{alarm.skip=AlarmSkipJson.decode(new JSONObject(skipped));}catch(JSONException bad){throw new IllegalArgumentException("The reviewed skipped occurrence could not be restored.");}rows.add(new Row(alarm,false,false));}}Group group=new Group(groupId,groupNonce,1,review,rows,"PREPARED","",false,false);put(c,group,own);return finish(c,group,own);}
 static Group retry(Context c,String id){BackupRuntime.admitted();long own=epoch.get();guard(own);return finish(c,get(c,id),own);}
 private static Group finish(Context c,Group initial,long own){Group group=initial;try{guard(own);if(group.cancellation||group.stage.equals("CANCELLED"))throw new IllegalArgumentException("This weekly application was cancelled. Review a new application.");access(c);List<Row> rows=new ArrayList<>(group.rows),already=new ArrayList<>();boolean allActive=true;try(Store store=Records.open(c)){for(Row row:rows){Alarm actual=store.alarm(row.id);if(!matches(group,row,actual)||!actual.enabled)allActive=false;else already.add(row.current(actual));}}if(group.activation&&allActive){group=group.change(already,"ACTIVE","All owned recurring alarms are already enabled. No new alarms were created.",true,false);put(c,group,own);return group;}if(group.stage.equals("ACTIVE"))throw new IllegalArgumentException("An active weekly alarm changed. Open individual alarms; it will not be replaced.");group.review.check(Naps.clock(c));
   try(Store store=Records.open(c)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{guard(own);for(Row row:rows){Alarm actual=store.alarm(row.id);if(actual==null){if(!group.stage.equals("PREPARED"))throw new IllegalArgumentException("An applied weekly alarm was deleted. It will not be recreated.");store.save(row.alarm());actual=store.alarm(row.id);}if(actual==null||!row.signature.equals(canonical(actual))||actual.enabled)throw new IllegalArgumentException("A weekly alarm slot changed. No unrelated alarm was overwritten.");}guard(own);db.setTransactionSuccessful();}finally{db.endTransaction();}}group=group.change(rows,"CREATED","",false,false);put(c,group,own);
   for(int n=0;n<rows.size();n++){guard(own);group.review.check(Naps.clock(c));access(c);Row row=rows.get(n);Alarm requested;try(Store store=Records.open(c)){Alarm actual=store.alarm(row.id);if(actual==null||actual.enabled||!row.signature.equals(canonical(actual)))throw new IllegalArgumentException("An owned weekly alarm changed before scheduling.");requested=Alarm.read(actual.json());requested.enabled=true;}AlarmScheduling.port.schedule(c,requested);guard(own);rows.set(n,row.scheduled());group=group.change(rows,"SCHEDULING","",false,false);put(c,group,own);}
   group.review.check(Naps.clock(c));group=group.change(rows,"ACTIVATING","",true,false);put(c,group,own);List<Row> active=new ArrayList<>();try(Store store=Records.open(c)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{guard(own);for(Row row:rows){Alarm actual=store.alarm(row.id);if(actual==null||actual.enabled||!row.signature.equals(canonical(actual)))throw new IllegalArgumentException("A weekly alarm changed before activation.");actual.enabled=true;store.save(actual);AlarmSkips.verify(store,actual);active.add(row.current(actual));}guard(own);group.review.check(Naps.clock(c));db.setTransactionSuccessful();}finally{db.endTransaction();}}group=group.change(active,"ACTIVE","Weekly recurring wake alarms are enabled.",true,false);put(c,group,own);return group;
  }catch(RuntimeException failure){Group attention=group.change(group.rows,"ATTENTION",NapProfilesRuntime.notice(failure),group.activation,group.cancellation);try{put(c,attention,own);return attention;}catch(RuntimeException lost){throw new IllegalStateException(NapProfilesRuntime.notice(failure)+" Reopen the weekly recovery record.",lost);}}}
 static Group cancel(Context c,String id){BackupRuntime.admitted();long own=epoch.get();guard(own);Group group=get(c,id);group=group.change(group.rows,"CANCELLING","",group.activation,true);put(c,group,own);List<Row> rows=new ArrayList<>(group.rows);int conflicts=0;try(Store store=Records.open(c)){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{guard(own);for(int n=0;n<rows.size();n++){Row row=rows.get(n);Alarm actual=store.alarm(row.id);if(actual==null){rows.set(n,row.cancelled());continue;}if(!matches(group,row,actual)){conflicts++;continue;}actual.enabled=false;store.save(actual);AlarmSkips.verify(store,actual);rows.set(n,row.current(actual));}guard(own);db.setTransactionSuccessful();}finally{db.endTransaction();}}group=group.change(rows,"CANCELLING","",group.activation,true);put(c,group,own);String issue=conflicts==0?"":conflicts+" changed alarms were left untouched. Detach the relation to manage them independently.";for(int n=0;n<rows.size();n++){guard(own);Row row=rows.get(n);if(row.cancelled)continue;Alarm actual;try(Store store=Records.open(c)){actual=store.alarm(row.id);}if(actual==null){rows.set(n,row.cancelled());continue;}if(actual.enabled||!row.signature.equals(canonical(actual)))continue;try{AlarmScheduling.port.schedule(c,actual);rows.set(n,row.cancelled());}catch(RuntimeException denied){issue="Owned rows are disabled. Retry system-schedule cleanup.";}}boolean cancelled=rows.stream().allMatch(r->r.cancelled);group=group.change(rows,cancelled?"CANCELLED":"ATTENTION",issue,group.activation,true);put(c,group,own);return group;}
 static void detach(Context c,String id){long own=epoch.get();guard(own);Group group=get(c,id);if(!Set.of("ACTIVE","CANCELLED","ATTENTION").contains(group.stage))throw new IllegalArgumentException("Finish or cancel this operation before detaching it.");synchronized(JOURNAL){guard(own);SharedPreferences.Editor edit=prefs(c).edit().remove("group_"+id);for(Row row:group.rows)edit.remove("row_"+row.id);if(!edit.commit())throw new IllegalStateException("Weekly relation could not be detached.");}}
 private NapProfilesWeekly(){}
}
